const ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_";

const CORE_SEGMENT = 0;
const DISCLOSED_SEGMENT = 1;
const PUBLISHER_SEGMENT = 3;

class BitReader {
    constructor(text) {
        this.bits = new Uint8Array(text.length * 6);
        for (let i = 0; i < text.length; i++) {
            const value = ALPHABET.indexOf(text[i]);
            if (value < 0)
                throw new Error("Invalid TC string character");
            for (let b = 0; b < 6; b++)
                this.bits[i * 6 + b] = (value >> (5 - b)) & 1;
        }
        this.position = 0;
    }

    read(length) {
        let value = 0;
        for (let i = 0; i < length; i++)
            value = value * 2 + (this.bits[this.position++] || 0);
        return value;
    }

    flag() {
        return this.read(1) === 1;
    }

    letters(count) {
        let text = "";
        for (let i = 0; i < count; i++)
            text += String.fromCharCode(65 + this.read(6));
        return text;
    }

    bitfield(length) {
        const set = [];
        for (let id = 1; id <= length; id++) {
            if (this.flag())
                set.push(id);
        }
        return set;
    }

    vendorSection() {
        const max = this.read(16);
        if (!this.flag())
            return { max, ids: this.bitfield(max) };
        const ids = [];
        const entries = this.read(12);
        for (let i = 0; i < entries; i++) {
            const isRange = this.flag();
            const start = this.read(16);
            const end = isRange ? this.read(16) : start;
            for (let id = start; id <= end; id++)
                ids.push(id);
        }
        return { max, ids };
    }
}

class BitWriter {
    constructor() {
        this.bits = [];
    }

    write(value, length) {
        for (let i = length - 1; i >= 0; i--)
            this.bits.push(Math.floor(value / Math.pow(2, i)) % 2);
    }

    flag(value) {
        this.bits.push(value ? 1 : 0);
    }

    letters(text) {
        for (const ch of text)
            this.write(ch.charCodeAt(0) - 65, 6);
    }

    bitfield(ids, length) {
        const set = new Set(ids);
        for (let id = 1; id <= length; id++)
            this.flag(set.has(id));
    }

    vendorSection(ids) {
        const sorted = Array.from(new Set(ids)).sort((a, b) => a - b);
        const max = sorted.length ? sorted[sorted.length - 1] : 0;
        const ranges = [];
        for (const id of sorted) {
            const last = ranges[ranges.length - 1];
            if (last && last[1] === id - 1)
                last[1] = id;
            else
                ranges.push([id, id]);
        }
        const rangeBits = 12 + ranges.reduce((sum, [a, b]) => sum + (a === b ? 17 : 33), 0);
        this.write(max, 16);
        if (rangeBits < max) {
            this.flag(true);
            this.write(ranges.length, 12);
            for (const [a, b] of ranges) {
                this.flag(a !== b);
                this.write(a, 16);
                if (a !== b)
                    this.write(b, 16);
            }
        } else {
            this.flag(false);
            this.bitfield(sorted, max);
        }
    }

    toString() {
        let text = "";
        for (let i = 0; i < this.bits.length; i += 6) {
            let value = 0;
            for (let b = 0; b < 6; b++)
                value = value * 2 + (this.bits[i + b] || 0);
            text += ALPHABET[value];
        }
        return text;
    }
}

export function decodeTCString(string) {
    const segments = string.split(".");
    const core = new BitReader(segments[0]);
    if (core.read(6) !== 2)
        throw new Error("Unsupported TC string version");
    const result = {
        version: 2,
        created: core.read(36) * 100,
        lastUpdated: core.read(36) * 100,
        cmpId: core.read(12),
        cmpVersion: core.read(12),
        consentScreen: core.read(6),
        consentLanguage: core.letters(2),
        vendorListVersion: core.read(12),
        tcfPolicyVersion: core.read(6),
        isServiceSpecific: core.flag(),
        useNonStandardTexts: core.flag(),
        specialFeatureOptins: core.bitfield(12),
        purposeConsents: core.bitfield(24),
        purposeLegitimateInterests: core.bitfield(24),
        purposeOneTreatment: core.flag(),
        publisherCC: core.letters(2),
        vendorConsents: core.vendorSection().ids,
        vendorLegitimateInterests: core.vendorSection().ids,
        publisherRestrictions: [],
        disclosedVendors: [],
    };
    const restrictions = core.read(12);
    for (let i = 0; i < restrictions; i++) {
        const purposeId = core.read(6);
        const restrictionType = core.read(2);
        const entries = core.read(12);
        const vendors = [];
        for (let e = 0; e < entries; e++) {
            const isRange = core.flag();
            const start = core.read(16);
            const end = isRange ? core.read(16) : start;
            for (let id = start; id <= end; id++)
                vendors.push(id);
        }
        result.publisherRestrictions.push({ purposeId, restrictionType, vendors });
    }
    for (let i = 1; i < segments.length; i++) {
        const reader = new BitReader(segments[i]);
        const type = reader.read(3);
        if (type === DISCLOSED_SEGMENT)
            result.disclosedVendors = reader.vendorSection().ids;
        else if (type === PUBLISHER_SEGMENT)
            result.publisherSegment = true;
    }
    return result;
}

export function encodeTCString(fields) {
    const core = new BitWriter();
    core.write(2, 6);
    core.write(Math.floor(fields.created / 100), 36);
    core.write(Math.floor(fields.lastUpdated / 100), 36);
    core.write(fields.cmpId, 12);
    core.write(fields.cmpVersion, 12);
    core.write(fields.consentScreen, 6);
    core.letters(fields.consentLanguage);
    core.write(fields.vendorListVersion, 12);
    core.write(fields.tcfPolicyVersion, 6);
    core.flag(fields.isServiceSpecific);
    core.flag(fields.useNonStandardTexts);
    core.bitfield(fields.specialFeatureOptins, 12);
    core.bitfield(fields.purposeConsents, 24);
    core.bitfield(fields.purposeLegitimateInterests, 24);
    core.flag(fields.purposeOneTreatment);
    core.letters(fields.publisherCC);
    core.vendorSection(fields.vendorConsents);
    core.vendorSection(fields.vendorLegitimateInterests);
    core.write(0, 12);
    const disclosed = new BitWriter();
    disclosed.write(DISCLOSED_SEGMENT, 3);
    disclosed.vendorSection(fields.disclosedVendors);
    return `${core}.${disclosed}`;
}

export { CORE_SEGMENT };
