export function indexMetadata(meta) {
    const vendors = new Map();
    const byPurpose = new Map();
    for (const key of Object.keys(meta.vendors)) {
        const vendor = meta.vendors[key];
        vendors.set(vendor.id, vendor);
        for (const purposeId of vendor.purposes) {
            let list = byPurpose.get(purposeId);
            if (!list)
                byPurpose.set(purposeId, (list = []));
            list.push(vendor.id);
        }
    }
    return { vendors, byPurpose, purposes: meta.purposes, version: meta.vendorListVersion, language: meta.language };
}

export async function loadMetadata(url) {
    const response = await window.fetch(url);
    return indexMetadata(await response.json());
}
