export const STORAGE_KEY = "tcf-consent";

export function readStoredString() {
    try {
        return window.localStorage.getItem(STORAGE_KEY);
    } catch (e) {
        return null;
    }
}

export function writeStoredString(value) {
    try {
        window.localStorage.setItem(STORAGE_KEY, value);
    } catch (e) {}
}
