const CMP_ID = 7;
const CMP_VERSION = 51;
const API_VERSION = "2.2";

function toMap(ids) {
    const map = {};
    for (const id of ids)
        map[id] = true;
    return map;
}

function fillMap(ids, universe) {
    const map = {};
    for (const id of universe)
        map[id] = ids.has(id);
    return map;
}

export class ConsentApi {
    constructor(tcString, decoded, meta) {
        this.tcString = tcString;
        this.decoded = decoded;
        this.meta = meta;
        this.listeners = new Map();
        this.nextListenerId = 0;
        this.consentedVendors = new Set(decoded.vendorConsents);
        this.liVendors = new Set(decoded.vendorLegitimateInterests);
        this.cache = new Map();
    }

    vendorMaps(filter) {
        const key = filter ? filter.join(",") : "";
        let maps = this.cache.get(key);
        if (!maps) {
            const universe = filter || Array.from(this.meta.vendors.keys());
            maps = {
                consents: fillMap(this.consentedVendors, universe),
                legitimateInterests: fillMap(this.liVendors, universe),
            };
            this.cache.set(key, maps);
        }
        return maps;
    }

    purposeMaps() {
        const all = [];
        for (let id = 1; id <= 10; id++)
            all.push(id);
        return {
            consents: fillMap(new Set(this.decoded.purposeConsents), all),
            legitimateInterests: fillMap(new Set(this.decoded.purposeLegitimateInterests), all),
        };
    }

    tcData(listenerId, filter) {
        const d = this.decoded;
        const data = {
            tcString: this.tcString,
            tcfPolicyVersion: d.tcfPolicyVersion,
            cmpId: CMP_ID,
            cmpVersion: CMP_VERSION,
            gdprApplies: true,
            eventStatus: "tcloaded",
            cmpStatus: "loaded",
            isServiceSpecific: d.isServiceSpecific,
            useNonStandardTexts: d.useNonStandardTexts,
            publisherCC: d.publisherCC,
            purposeOneTreatment: d.purposeOneTreatment,
            purpose: this.purposeMaps(),
            vendor: this.vendorMaps(filter),
            specialFeatureOptins: toMap(d.specialFeatureOptins),
            publisher: { consents: {}, legitimateInterests: {}, customPurpose: { consents: {}, legitimateInterests: {} }, restrictions: {} },
        };
        for (const restriction of d.publisherRestrictions) {
            data.publisher.restrictions[restriction.purposeId] = restriction.vendors.reduce((map, id) => {
                map[id] = restriction.restrictionType;
                return map;
            }, {});
        }
        if (listenerId !== undefined)
            data.listenerId = listenerId;
        return data;
    }

    ping() {
        return {
            gdprApplies: true,
            cmpLoaded: true,
            cmpStatus: "loaded",
            displayStatus: "hidden",
            apiVersion: API_VERSION,
            cmpVersion: CMP_VERSION,
            cmpId: CMP_ID,
            gvlVersion: this.meta.version,
            tcfPolicyVersion: this.decoded.tcfPolicyVersion,
        };
    }

    handle(command, version, callback, parameter) {
        if (typeof callback !== "function")
            return;
        if (version !== 2 && command !== "ping") {
            callback(null, false);
            return;
        }
        switch (command) {
        case "ping":
            callback(this.ping(), true);
            break;
        case "getTCData":
            callback(this.tcData(undefined, Array.isArray(parameter) ? parameter : null), true);
            break;
        case "addEventListener": {
            const id = this.nextListenerId++;
            this.listeners.set(id, callback);
            callback(this.tcData(id), true);
            break;
        }
        case "removeEventListener":
            callback(this.listeners.delete(parameter), true);
            break;
        default:
            callback(null, false);
        }
    }
}
