import { ConsentApi } from "./api.js";
import { decodeTCString } from "./tcstring.js";
import { loadMetadata } from "./meta.js";
import { readStoredString, writeStoredString } from "./store.js";

const META_URL = "data/tp/consent/meta.json";
const FALLBACK_TC_STRING = __FALLBACK_TC_STRING__;
const CALL_KEY = "__tcfapiCall";
const RETURN_KEY = "__tcfapiReturn";

function boot() {
    performance.mark("consent-wrapper-start");
    const stub = window.__tcfapi;
    const queued = (stub && stub.a) || [];
    let tcString = readStoredString();
    if (!tcString) {
        tcString = FALLBACK_TC_STRING;
        writeStoredString(tcString);
    }
    const decoded = decodeTCString(tcString);
    let api = null;
    const waiting = [];

    function dispatch(args) {
        if (api)
            api.handle(args[0], args[1], args[2], args[3]);
        else
            waiting.push(args);
    }

    const entry = function () {
        dispatch(arguments);
    };
    entry.wrapped = true;
    entry.a = [];
    window.__tcfapi = entry;
    window.__uspapi = function (command, version, callback) {
        if (typeof callback === "function")
            callback(command === "getUSPData" ? { version: 1, uspString: "1---" } : null, command === "getUSPData");
    };

    window.addEventListener("message", (event) => {
        const raw = event.data;
        const isString = typeof raw === "string";
        if (isString ? raw.indexOf(CALL_KEY) === -1 : !raw || typeof raw !== "object")
            return;
        let payload;
        try {
            payload = isString ? JSON.parse(raw) : raw;
        } catch (e) {
            return;
        }
        const call = payload && payload[CALL_KEY];
        if (!call || !event.source)
            return;
        dispatch([call.command, call.version, (returnValue, success) => {
            const reply = { [RETURN_KEY]: { returnValue, success, callId: call.callId } };
            event.source.postMessage(isString ? JSON.stringify(reply) : reply, "*");
        }, call.parameter]);
    });

    const ready = loadMetadata(META_URL).then((meta) => {
        api = new ConsentApi(tcString, decoded, meta);
        for (const args of queued.concat(waiting.splice(0)))
            api.handle(args[0], args[1], args[2], args[3]);
        performance.mark("consent-wrapper-ready");
        window.__benchmarkWork?.settled("consent");
    });
    window.__benchmarkWork?.track(ready);
}

boot();
